import org.audiveris.omr.sheet.Book;
import java.nio.file.*;
import java.util.*;
import java.awt.geom.Point2D;
public class RealPartMeasuresImageProbe extends RealLedgerMembershipImageProbe {
 private final Object actual;
 public RealPartMeasuresImageProbe(Book book,SortedSet<Integer> ids){super(book,ids);actual=book;}
 static String partbar(Object b)throws Exception{if(b==null)return "null";List<String> rows=new ArrayList<>();for(Object sb:(List<?>)call(b,"getStaffBarlines"))rows.add("{\"staff\":"+call(call(sb,"getStaff"),"getId")+",\"members\":"+bars((List<?>)call(sb,"getMembers"))+"}");return "["+String.join(",",rows)+"]";}
 static String bars(List<?> members)throws Exception{List<String> rows=new ArrayList<>();for(Object n:members)rows.add("{\"bounds\":"+rect(call(n,"getBounds"))+",\"shape\":\""+call(n,"getShape")+"\",\"grade\":"+call(n,"getGrade")+",\"frozen\":"+call(n,"isFrozen")+",\"manual\":"+call(n,"isManual")+"}");return "["+String.join(",",rows)+"]";}
 public void process(){try{
  Object stub=((List<?>)call(actual,"getStubs")).get(0);call(stub,"reachStep",c("step.OmrStep").getField("TEXTS").get(null),false);Object sheet=call(stub,"getSheet");List<String> systems=new ArrayList<>();
  for(Object sys:(List<?>)call(sheet,"getSystems")){Object builder=make("sheet.rhythm.MeasuresBuilder",sys);List<String> groups=new ArrayList<>(),staffbars=new ArrayList<>(),parts=new ArrayList<>();List<?> actualParts=new ArrayList<>((List<?>)call(sys,"getParts"));
   for(Object staff:(List<?>)call(sys,"getStaves")){List<String> gs=new ArrayList<>();for(Object g:(List<?>)call(builder,"buildGroups",call(staff,"getBarlines"))){Object center=getField(g,"center"),dsk=getField(g,"dsk");gs.add("{\"members\":"+bars((List<?>)g)+",\"center\":["+((Point2D)center).getX()+","+((Point2D)center).getY()+"],\"deskew_x\":"+((Point2D)dsk).getX()+"}");}groups.add("{\"staff\":"+call(staff,"getId")+",\"groups\":["+String.join(",",gs)+"]}");}
   call(builder,"buildMeasures");for(Object staff:(List<?>)call(sys,"getStaves")){List<String> bs=new ArrayList<>();for(Object sb:(List<?>)call(staff,"getStaffBarlines")){String style=call(sb,"getStyle")==null?"null":"\""+call(sb,"getStyle")+"\"";bs.add("{\"bounds\":"+rect(call(sb,"getBounds"))+",\"members\":"+bars((List<?>)call(sb,"getMembers"))+",\"style\":"+style+",\"grade\":"+call(sb,"getGrade")+",\"frozen\":"+call(sb,"isFrozen")+",\"manual\":"+call(sb,"isManual")+",\"back_to_back\":"+call(sb,"isBackToBack")+"}");}staffbars.add("{\"staff\":"+call(staff,"getId")+",\"bars\":["+String.join(",",bs)+"]}");}
   for(Object part:actualParts){if(!((List<?>)call(sys,"getParts")).contains(part))throw new IllegalStateException("Part replaced");List<String> ids=new ArrayList<>(),ms=new ArrayList<>();for(Object staff:(List<?>)call(part,"getStaves"))ids.add(call(staff,"getId").toString());List<?> measures=(List<?>)call(part,"getMeasures"),stacks=(List<?>)call(sys,"getStacks");Object left=c("util.HorizontalSide").getField("LEFT").get(null),right=c("util.HorizontalSide").getField("RIGHT").get(null);Object previousRight=null;
    for(Object m:measures){Object stack=call(m,"getStack"),containedLeft=call(m,"getLeftPartBarline"),effectiveLeft=call(m,"getPartBarlineOn",left),rb=call(m,"getRightPartBarline");int si=stacks.indexOf(stack);if(si<0||!((List<?>)call(stack,"getMeasures")).contains(m)||call(m,"getPart")!=part)throw new IllegalStateException("Measure/Stack owner changed");List<String> xs=new ArrayList<>();for(Object staff:(List<?>)call(part,"getStaves"))xs.add("{\"staff\":"+call(staff,"getId")+",\"left\":"+call(m,"getAbscissa",left,staff)+",\"right\":"+call(m,"getAbscissa",right,staff)+"}");Object expectedLeft=containedLeft!=null?containedLeft:previousRight!=null?previousRight:call(part,"getLeftPartBarline");ms.add("{\"stack_index\":"+(si+1)+",\"abscissae\":["+String.join(",",xs)+"],\"contained_left\":"+partbar(containedLeft)+",\"effective_left\":"+partbar(effectiveLeft)+",\"right_bar\":"+partbar(rb)+",\"same_effective_left_object\":"+(effectiveLeft==expectedLeft)+",\"same_Part_object\":true,\"same_Stack_member_object\":true}");previousRight=rb;}
    parts.add("{\"part\":"+call(part,"getId")+",\"staffs\":["+String.join(",",ids)+"],\"left_bar\":"+partbar(call(part,"getLeftPartBarline"))+",\"measures\":["+String.join(",",ms)+"]}");}

   systems.add("{\"system\":"+call(sys,"getId")+",\"groups\":["+String.join(",",groups)+"],\"staff_bars\":["+String.join(",",staffbars)+"],\"parts\":["+String.join(",",parts)+"],\"stack_count\":"+((List<?>)call(sys,"getStacks")).size()+"}");
  }
  Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"scope\":\"unchanged original normal reachStep TEXTS before MEASURES in memory without intermediate SIG serialization and original MeasuresBuilder; actual Part/Staff/bar groups, PartBarline members and per-Staff Measure abscissae/shared Stack references before CHORDS, no native outputs\",\"systems\":["+String.join(",",systems)+"]}\n");
 }catch(Exception e){throw new RuntimeException(e);}}
 static Object getField(Object o,String name)throws Exception{var f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
}
